// Pagination limits. A read without a limit is a production incident waiting
// for the table to grow, so one is always applied.
const (
	DefaultLimit = 50
	MaxLimit     = 500
)

// MaxFilterDepth bounds how far a filter may reach across relations.
//
// The filter types are mutually recursive, so a client can nest one as deep as
// it likes, and each level is another correlated subquery. A bound is the
// difference between an expensive query somebody asked for and an arbitrarily
// expensive one they were allowed to.
const MaxFilterDepth = 3

// filterScope is what rendering one level of a filter needs.
type filterScope struct {
	claims tenancy.Claims
	// as qualifies this level's columns. Inside a subquery two tables are in
	// scope, and an unqualified name there resolves to whichever one happens to
	// have it — a silent correlation to the wrong row rather than an error.
	as string
	// link qualifies the join table of a many-to-many at this level.
	link  string
	depth int
}

// newFilterScope starts at the table being read.
func newFilterScope(claims tenancy.Claims, table string) filterScope {
	return filterScope{claims: claims, as: table}
}

// ok refuses a filter nested deeper than this will render.
func (s filterScope) ok() error {
	if s.depth > MaxFilterDepth {
		return rigerr.Invalid("a filter may reach across at most %s relations", strconv.Itoa(MaxFilterDepth))
	}
	return nil
}

// at qualifies a condition with this level's alias.
func (s filterScope) at(c query.Cond) query.Cond {
	c.Table = s.as
	return c
}

// into opens the next level down, with aliases of its own so that a
// self-reference at two depths does not shadow itself.
func (s filterScope) into() filterScope {
	d := s.depth + 1
	return filterScope{claims: s.claims, as: "r" + strconv.Itoa(d), link: "l" + strconv.Itoa(d), depth: d}
}

// belongsTo opens a subquery on the row this one points at.
func (s filterScope) belongsTo(farTable, farColumn, localColumn string) (filterScope, string, string) {
	in := s.into()
	return in, farTable + " " + in.as, in.as + "." + farColumn + " = " + s.as + "." + localColumn
}

// hasMany opens a subquery on the rows that point at this one.
func (s filterScope) hasMany(farTable, farColumn, pk string) (filterScope, string, string) {
	in := s.into()
	return in, farTable + " " + in.as, in.as + "." + farColumn + " = " + s.as + "." + pk
}

// throughLink opens a subquery on the far side of a join table.
//
// The condition is on the far resource and the link is only how you get there,
// which is why this is a chain rather than a table name.
func (s filterScope) throughLink(linkTable, nearColumn, farTable, farColumn, pk string) (filterScope, string, string) {
	in := s.into()
	from := linkTable + " " + in.link +
		" JOIN " + farTable + " " + in.as +
		" ON " + in.as + ".id = " + in.link + "." + farColumn
	return in, from, in.link + "." + nearColumn + " = " + s.as + "." + pk
}

// tenant scopes a subquery to the caller's tenant.
//
// This is the predicate the whole design turns on. Without it a condition on a
// related table is answered from every tenant's rows: the caller cannot read
// the far row, but learns it exists from which of their own rows come back.
func (s filterScope) tenant(column string) query.Cond {
	return s.at(query.Eq(column, s.claims.TenantID))
}

// live excludes rows somebody retired, so a deleted row is not a way to find
// its neighbours.
func (s filterScope) live(column string) query.Cond {
	return s.at(query.IsNull(column))
}

// original excludes the history, which is never what a condition on a relation
// means.
func (s filterScope) original(column string, value any) query.Cond {
	return s.at(query.Eq(column, value))
}

// aliased is this scope under a different name, for the far side of a join.
//
// The alias space is separate from the one a subquery uses — o1 here, r1
// there — because a join lives in the same statement as the conditions and a
// subquery that reused the name would resolve its own columns against it.
func (s filterScope) aliased(alias string) filterScope {
	return filterScope{claims: s.claims, as: alias, depth: s.depth}
}

// orderJoin reaches a related row so that its columns can be ordered by, and
// returns the scope its predicates belong to.
//
// LEFT rather than INNER, and that is the whole reason this is a join at all:
// it is here to read a value, not to decide anything. An inner join would drop
// every row whose foreign key is null, so asking for an order would quietly
// shorten the list.
func (s filterScope) orderJoin(farTable, alias, farColumn, localColumn string) (filterScope, query.Join) {
	return s.aliased(alias), query.Join{
		Table: farTable + " " + alias,
		On:    alias + "." + farColumn + " = " + s.as + "." + localColumn,
	}
}

// Config is what a Store needs beyond a connection.
//
// Taken by value, so that giving a store something else to hold is a new field
// rather than a signature change every caller has to follow.
type Config struct {
	// Logger is where the invalidation channel reports losing touch with Postgres,
	// which is the one thing about this cache worth hearing about: the fallback is
	// to read every row again, and that is correct and silent. Nil takes
	// slog.Default.
	//
	//	store.New(pool, store.Config{Logger: app.Logger})
	Logger *slog.Logger
}

// Store holds the connection pool and hands out repositories.
type Store struct {
	pool      *pgxpool.Pool
	cacheBus  *cache.Bus
	memoCache *rowCache[*model.Memo]

	Memos MemoRepository
}

// New builds a store over a connection pool.
func New(pool *pgxpool.Pool, cfg Config) *Store {
	s := &Store{pool: pool}

	// The invalidation channel, listening from here on. Every held row is
	// withdrawn over it by the transaction that changed the row, so this is what
	// makes the lifetime a backstop rather than a promise about staleness.
	s.cacheBus = cache.NewBus(cache.BusConfig{
		Pool:    pool,
		Channel: "rig_cache",
		// The one line anybody reads when this stops working. Losing the channel is
		// correct and silent — the caches go dead and every read is a query again
		// — so nothing else about the process would say so.
		Logger: cfg.Logger,
	})

	s.memoCache = newRowCache[*model.Memo](30*time.Second, 50000)
	s.memoCache.serve(s.cacheBus, "memo")

	// After the caches are attached, so nothing can be delivered a notification
	// for a topic that is not registered yet.
	s.cacheBus.Start()

	s.Memos = &memoRepo{db: s}
	return s
}

// connFor returns the transaction on the context when there is one, and the
// pool otherwise.
//
// This is what lets a repository method work the same whether it was called
// directly or inside a transaction someone else opened — InTx, a hook, or
// the record an idempotent write is being kept in. The context is the whole of
// it: an argless version reading context.Background() can only ever answer
// with the pool, and a write that answered with the pool would commit whatever
// the surrounding transaction went on to do.
func (s *Store) connFor(ctx context.Context) dbx.Conn {
	if tx, ok := dbx.Tx(ctx); ok {
		return tx
	}
	return s.pool
}

// Pool exposes the underlying pool, for the rare query the generated
// repositories do not cover.
func (s *Store) Pool() *pgxpool.Pool { return s.pool }

// InTx runs fn inside one transaction. Repository calls made with the context
// it provides join that transaction rather than opening their own.
func (s *Store) InTx(ctx context.Context, fn func(ctx context.Context) error) error {
	return dbx.InTx(ctx, s.pool, func(ctx context.Context, _ dbx.Conn) error { return fn(ctx) })
}

// Close stops listening for invalidations.
//
// Worth registering beside the rest of a program's shutdown:
//
//	app.CloseWithin("store", 5*time.Second, repos.Close)
//
// and safe to leave out. A bus that has stopped is a bus that is not live, and
// a cache that is not live reads through and holds nothing — so forgetting
// this costs a connection held until the process exits rather than a row
// somebody cannot withdraw.
func (s *Store) Close(ctx context.Context) error {
	return s.cacheBus.Close(ctx)
}

// joinColumns renders a column list. The names come from generated constants,
// never from a request.
func joinColumns(columns []string) string { return strings.Join(columns, ", ") }

// placeholders renders $1, $2, ... for n values.
func placeholders(n int) string {
	parts := make([]string, n)
	for i := range parts {
		parts[i] = "$" + strconv.Itoa(i+1)
	}
	return strings.Join(parts, ", ")
}

// assignments renders `col = $1, col = $2, ...` for an update.
func assignments(columns []string) string {
	parts := make([]string, len(columns))
	for i, c := range columns {
		parts[i] = c + " = $" + strconv.Itoa(i+1)
	}
	return strings.Join(parts, ", ")
}

// writeError turns a database failure into one a client can act on.
//
// A constraint violation is the caller's mistake and deserves a status that
// says so; anything else is the server's problem and says nothing more,
// because the detail of an internal failure is exactly the kind of thing that
// leaks a table name.
func writeError(err error, table string) error {
	switch {
	case dbx.IsUniqueViolation(err):
		return rigerr.Conflict("that %s already exists", table).Wrap(err)
	case dbx.IsForeignKeyViolation(err):
		return rigerr.Conflict("a related row is missing or still in use").Wrap(err)
	case dbx.IsCheckViolation(err):
		return rigerr.Invalid("the %s failed a database constraint", table).Wrap(err)
	case dbx.IsNotNullViolation(err):
		return rigerr.Invalid("a required %s field was not given", table).Wrap(err)
	default:
		return rigerr.Internal(err, "write %s", table)
	}
}

// rowCacheServed is the channel a rowCache was attached to, or nil for one
// that never was.
type rowCacheServed struct {
	bus   *cache.Bus
	topic *cache.Topic
}

// rowCache holds one table's rows between requests.
//
// Every entry in it is withdrawn by a Postgres NOTIFY published inside the
// transaction of the write that made it wrong, so the lifetime is the backstop
// rather than the guarantee. Nothing here is shared between replicas except
// the word "forget".
type rowCache[V any] struct {
	m *cache.Map[V]
	// An atomic pointer rather than a field, because serve happens after New and
	// on a different goroutine than the reads.
	served atomic.Pointer[rowCacheServed]
}

// newRowCache builds a cache that holds nothing until it is served.
func newRowCache[V any](ttl time.Duration, maxEntries int) *rowCache[V] {
	c := &rowCache[V]{}
	c.m = cache.NewMap[V](cache.MapConfig{TTL: ttl, MaxEntries: maxEntries, Live: c.live})
	return c
}

// live reports whether an entry could be withdrawn if one were held.
//
// Two ways to answer no, and both have to: never attached to a channel, and
// attached to one that has dropped. Every mistake around the lifecycle lands
// on one of them, which is what makes those mistakes cost latency rather than
// correctness — a cache that is not live reads through and stores nothing.
func (c *rowCache[V]) live() bool {
	s := c.served.Load()
	switch {
	case s == nil:
		// Never served. There is no channel, so nothing could withdraw an entry and
		// nothing may be kept.
		return false
	}
	return s.bus.Live()
}

// serve attaches this cache to a bus, so its entries can be withdrawn.
//
// A nil bus leaves it unserved, and therefore dead: a cache with no channel is
// a plain time-to-live over the application's own rows, which is the trade
// this whole mechanism exists to refuse. Reading through costs queries;
// holding a row nothing can withdraw costs correctness, and only one of those
// is worth defaulting to.
func (c *rowCache[V]) serve(bus *cache.Bus, topic string) {
	if bus == nil {
		return
	}
	c.served.Store(&rowCacheServed{bus: bus, topic: bus.Serve(topic, c.m)})
}

// load answers from the cache, or reads through it.
func (c *rowCache[V]) load(key string, fn func() (V, error)) (V, error) {
	return c.m.Load(key, fn)
}

// forget withdraws one row: here once the change lands, and everywhere else on
// the transaction that made it.
//
// Both, and each covers what the other cannot.
//
// The notification is what reaches the other replicas, and it is published
// inside the writing transaction because that is the whole mechanism: Postgres
// delivers it when that transaction commits and throws it away if it rolls
// back, so the invalidation is atomic with the write and nobody forgets a row
// a rollback put back.
//
// What it cannot do is reach *this* replica in time. It travels out through
// Postgres and back in on the listener's own connection, which takes some
// moments — and those moments belong to the caller who just wrote, who would
// spend them reading the row as it was. Somebody who saves a change and is
// shown the old value has been told their write did not happen. So the local
// drop is registered on the commit instead, where it runs before the write
// returns to whoever asked for it.
//
// Dropping an entry that a rollback made valid again costs one query, and
// AfterCommit does not run on a rollback anyway. With no transaction at all it
// runs immediately, which is the whole of what is available and the whole of
// what is needed.
func (c *rowCache[V]) forget(ctx context.Context, key string) error {
	dbx.AfterCommit(ctx, func() { c.m.Forget(key) })

	s := c.served.Load()
	tx, ok := dbx.Tx(ctx)
	if !ok || s == nil || s.topic == nil {
		// No channel, or no transaction to publish on. The drop above is all there is,
		// and there is no other replica it could have reached.
		return nil
	}
	return s.topic.Forget(ctx, tx, key)
}
